// Command kvhttp is an in-memory HTTP key-value server.
//
// Usage: kvhttp <port>
package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"
)

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, "kvhttp:", err)
		os.Exit(1)
	}
}

func run(args []string) error {
	if len(args) != 1 {
		return errors.New("usage: kvhttp <port>")
	}
	port, err := strconv.Atoi(args[0])
	if err != nil || port < 1 || port > 65535 {
		return fmt.Errorf("invalid port %q", args[0])
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	addr := net.JoinHostPort("127.0.0.1", strconv.Itoa(port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return fmt.Errorf("listen: %w", err)
	}

	srv := &http.Server{
		Handler:           NewServer(NewStore()),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       60 * time.Second,
		WriteTimeout:      60 * time.Second,
		IdleTimeout:       120 * time.Second,
		MaxHeaderBytes:    64 << 10,
	}

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()
	slog.Info("listening", "addr", addr)

	select {
	case err := <-errc:
		return fmt.Errorf("serve: %w", err)
	case <-ctx.Done():
	}

	sctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := srv.Shutdown(sctx); err != nil {
		return fmt.Errorf("shutdown: %w", err)
	}
	return nil
}

package main

import (
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"strconv"
	"strings"
)

// maxValueSize is the largest value accepted by PUT /kv/<key>.
const maxValueSize = 1 << 20

// Server routes HTTP requests to a Store.
//
// Routing is done by hand rather than with http.ServeMux so that paths are
// never cleaned or redirected: the spec requires exact status codes for
// malformed keys such as "/kv/a/b" or "/kv/".
type Server struct {
	store *Store
}

// NewServer returns a Server backed by store.
func NewServer(store *Store) *Server {
	return &Server{store: store}
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path
	switch {
	case path == "/health":
		if !allow(w, r, http.MethodGet) {
			return
		}
		writeBody(w, http.StatusOK, "text/plain; charset=utf-8", []byte("ok"))
	case path == "/kv":
		if !allow(w, r, http.MethodGet) {
			return
		}
		s.handleList(w)
	case strings.HasPrefix(path, "/kv/"):
		if !allow(w, r, http.MethodGet, http.MethodPut, http.MethodDelete) {
			return
		}
		key := strings.TrimPrefix(path, "/kv/")
		if !validKey(key) {
			writeError(w, http.StatusBadRequest)
			return
		}
		switch r.Method {
		case http.MethodGet:
			s.handleGet(w, key)
		case http.MethodPut:
			s.handlePut(w, r, key)
		case http.MethodDelete:
			s.handleDelete(w, key)
		}
	default:
		writeError(w, http.StatusNotFound)
	}
}

func (s *Server) handleList(w http.ResponseWriter) {
	body, err := json.Marshal(s.store.Keys())
	if err != nil {
		slog.Error("marshal keys", "err", err)
		writeError(w, http.StatusInternalServerError)
		return
	}
	writeBody(w, http.StatusOK, "application/json", body)
}

func (s *Server) handleGet(w http.ResponseWriter, key string) {
	v, ok := s.store.Get(key)
	if !ok {
		writeError(w, http.StatusNotFound)
		return
	}
	writeBody(w, http.StatusOK, "application/octet-stream", v)
}

func (s *Server) handlePut(w http.ResponseWriter, r *http.Request, key string) {
	if r.ContentLength > maxValueSize {
		writeError(w, http.StatusRequestEntityTooLarge)
		return
	}
	value, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxValueSize))
	if err != nil {
		if _, ok := errors.AsType[*http.MaxBytesError](err); ok {
			writeError(w, http.StatusRequestEntityTooLarge)
			return
		}
		writeError(w, http.StatusBadRequest)
		return
	}
	status := http.StatusOK
	if s.store.Put(key, value) {
		status = http.StatusCreated
	}
	writeBody(w, status, "", nil)
}

func (s *Server) handleDelete(w http.ResponseWriter, key string) {
	if !s.store.Delete(key) {
		writeError(w, http.StatusNotFound)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// allow reports whether r.Method is one of methods. If not, it writes a 405
// response with an Allow header and returns false.
func allow(w http.ResponseWriter, r *http.Request, methods ...string) bool {
	for _, m := range methods {
		if r.Method == m {
			return true
		}
	}
	w.Header().Set("Allow", strings.Join(methods, ", "))
	writeError(w, http.StatusMethodNotAllowed)
	return false
}

// validKey reports whether key matches [A-Za-z0-9_-]{1,64}.
func validKey(key string) bool {
	if len(key) == 0 || len(key) > 64 {
		return false
	}
	for i := range len(key) {
		c := key[i]
		switch {
		case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

func writeError(w http.ResponseWriter, status int) {
	writeBody(w, status, "text/plain; charset=utf-8", []byte(http.StatusText(status)))
}

// writeBody writes a complete response with an explicit Content-Length.
func writeBody(w http.ResponseWriter, status int, contentType string, body []byte) {
	h := w.Header()
	if contentType != "" {
		h.Set("Content-Type", contentType)
	}
	h.Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	if len(body) > 0 {
		if _, err := w.Write(body); err != nil {
			slog.Debug("write response", "err", err)
		}
	}
}

package main

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
)

func do(t *testing.T, h http.Handler, method, path string, body []byte) *httptest.ResponseRecorder {
	t.Helper()
	var r io.Reader
	if body != nil {
		r = bytes.NewReader(body)
	}
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(method, path, r))
	return rec
}

func TestRoutes(t *testing.T) {
	t.Parallel()
	h := NewServer(NewStore())
	steps := []struct {
		method, path, body string
		status             int
		want               string
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/health", "", 405, ""},
		{"GET", "/kv", "", 200, "[]"},
		{"PUT", "/kv/b", "2", 201, ""},
		{"PUT", "/kv/a", "1", 201, ""},
		{"PUT", "/kv/a", "one", 200, ""},
		{"GET", "/kv/a", "", 200, "one"},
		{"GET", "/kv", "", 200, `["a","b"]`},
		{"DELETE", "/kv/a", "", 204, ""},
		{"DELETE", "/kv/a", "", 404, ""},
		{"GET", "/kv/a", "", 404, ""},
		{"PATCH", "/kv/a", "", 405, ""},
		{"POST", "/kv", "", 405, ""},
		{"GET", "/kv/", "", 400, ""},
		{"GET", "/kv/a/b", "", 400, ""},
		{"GET", "/kv/bad.key", "", 400, ""},
		{"GET", "/kv/" + strings.Repeat("x", 65), "", 400, ""},
		{"GET", "/kv/" + strings.Repeat("x", 64), "", 404, ""},
		{"GET", "/nope", "", 404, ""},
		{"GET", "/", "", 404, ""},
		{"GET", "/health/", "", 404, ""},
	}
	for _, s := range steps {
		var body []byte
		if s.body != "" {
			body = []byte(s.body)
		}
		rec := do(t, h, s.method, s.path, body)
		if rec.Code != s.status {
			t.Fatalf("%s %s: status %d, want %d", s.method, s.path, rec.Code, s.status)
		}
		if s.want != "" && rec.Body.String() != s.want {
			t.Fatalf("%s %s: body %q, want %q", s.method, s.path, rec.Body.String(), s.want)
		}
	}
}

func TestValueSizeLimit(t *testing.T) {
	t.Parallel()
	h := NewServer(NewStore())
	if rec := do(t, h, "PUT", "/kv/big", make([]byte, maxValueSize)); rec.Code != 201 {
		t.Fatalf("1 MiB value: status %d, want 201", rec.Code)
	}
	if rec := do(t, h, "PUT", "/kv/big", make([]byte, maxValueSize+1)); rec.Code != 413 {
		t.Fatalf("oversized value: status %d, want 413", rec.Code)
	}
}

func TestConcurrentPuts(t *testing.T) {
	t.Parallel()
	h := NewServer(NewStore())
	var wg sync.WaitGroup
	for i := range 64 {
		wg.Go(func() {
			key := fmt.Sprintf("k%d", i)
			if rec := do(t, h, "PUT", "/kv/"+key, []byte(key)); rec.Code != 201 {
				t.Errorf("PUT %s: status %d", key, rec.Code)
			}
		})
	}
	wg.Wait()
	if n := len(h.store.Keys()); n != 64 {
		t.Fatalf("got %d keys, want 64", n)
	}
}

package main

import (
	"maps"
	"slices"
	"sync"
)

// Store is a concurrency-safe in-memory key-value store.
// Stored values are treated as immutable once written.
type Store struct {
	mu   sync.RWMutex
	data map[string][]byte
}

// NewStore returns an empty Store.
func NewStore() *Store {
	return &Store{data: make(map[string][]byte)}
}

// Get returns the value for key and whether it was present.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// Put stores value under key and reports whether the key was newly created.
func (s *Store) Put(key string, value []byte) (created bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, existed := s.data[key]
	s.data[key] = value
	return !existed
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.data[key]
	delete(s.data, key)
	return ok
}

// Keys returns all keys in ascending order.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := slices.Collect(maps.Keys(s.data))
	s.mu.RUnlock()
	slices.Sort(keys)
	if keys == nil {
		keys = []string{}
	}
	return keys
}
